    background: "transparent",
    color: "#b6c4d6",
    font: "inherit",
    cursor: "pointer",
    touchAction: "manipulation",
  });
  closeBtn.addEventListener("click", () => {
    window.dispatchEvent(new CustomEvent("ui:requestDialogClose", {
      detail: { sessionId },
    }));
  });
  footer.appendChild(closeBtn);
  panel.appendChild(footer);
}

