// display/ui/overlayUtils.js
// Shared utilities, panel management, tooltips, and standalone UI widgets.

import { getHighscoreVersionLabel, getHighscores } from '../../cloud/tombstones/client.js';
import { GAME_ICON_FONT_FAMILY, GAME_LOG_FONT_FAMILY, GAME_TEXT_FONT_FAMILY } from '../fonts.js';
import { CHARACTER_MENU_TAB_GLYPHS } from './iconGlyphs.js';

export const PANEL_Z_BASE = 1200;
export let _panelZCounter = PANEL_Z_BASE;
export const UI_ROOT_Z_INDEX = 1000;
export const SPEECH_BUBBLE_LAYER_Z_INDEX = 2147483000;
export const DIALOG_LAYER_Z_INDEX = 2147483100;

/** Increment and return the panel z-index counter. */
export function bumpPanelZ() {
  _panelZCounter += 1;
  return _panelZCounter;
}

export const CHARACTER_SLOT_ORDER = Object.freeze([
  'brain',
  'weapon',
  'armor',
  'head',
  'neck',
  'belt',
  'gloves',
  'offhand',
  'ring1',
  'ring2',
  'legs',
  'feet',
  'ammo',
  'ranged',
]);
export const CHARACTER_MENU_TABS = Object.freeze([
  { key: 'character', icon: CHARACTER_MENU_TAB_GLYPHS.character, label: 'Character', eventName: 'ui:openCharacter' },
  { key: 'inventory', icon: CHARACTER_MENU_TAB_GLYPHS.inventory, label: 'Inventory', eventName: 'ui:openInventory' },
  { key: 'equipment', icon: CHARACTER_MENU_TAB_GLYPHS.equipment, label: 'Equipment', eventName: 'ui:openEquipment' },
  { key: 'quests', icon: CHARACTER_MENU_TAB_GLYPHS.quests, label: 'Quests', eventName: 'ui:openQuests' },
  { key: 'settings', icon: CHARACTER_MENU_TAB_GLYPHS.settings, label: 'Settings', eventName: 'ui:openSettings' },
]);
export const INTERACTION_POPUP_ARM_DELAY_MS = 250;

// --- _itemTooltip module state (mutable let) ---
let _itemTooltip = null;

export function getItemTooltip() {
  return _itemTooltip;
}

export function setItemTooltip(el) {
  _itemTooltip = el;
}

/**
 * @param {HTMLDivElement} host
 * @param {'character'|'inventory'|'equipment'|'settings'} activeKey
 */
export function appendCharacterMenuTabs(host, activeKey) {
  const tabs = document.createElement('div');
  Object.assign(tabs.style, {
    position: 'sticky',
    top: '0',
    zIndex: '3',
    display: 'grid',
    gridTemplateColumns: 'repeat(5, minmax(0, 1fr))',
    gap: '6px',
    marginBottom: '10px',
    paddingBottom: '8px',
    background: UX_THEME.panelBg,
    backdropFilter: 'blur(6px)',
  });

  for (const tab of CHARACTER_MENU_TABS) {
    const btn = document.createElement('button');
    decorateButton(btn);
    Object.assign(btn.style, {
      minHeight: '46px',
      padding: '6px 4px',
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      gap: '3px',
      borderRadius: '8px',
    });
    const isActive = tab.key === activeKey;
    if (isActive) {
      btn.style.background = UX_THEME.surfaceSelected;
      btn.style.borderColor = UX_THEME.accentBorder;
      btn.style.color = UX_THEME.textStrong;
      btn.style.boxShadow = UX_THEME.accentGlow;
    }

    const icon = document.createElement('span');
    icon.textContent = tab.icon;
    icon.style.lineHeight = '1';
    icon.style.fontSize = '16px';
    icon.style.fontFamily = GAME_ICON_FONT_FAMILY;
    const label = document.createElement('span');
    label.textContent = tab.label;
    label.style.fontSize = '11px';
    label.style.lineHeight = '1';
    btn.title = tab.label;
    btn.setAttribute('aria-label', tab.label);
    if (isActive) btn.setAttribute('aria-current', 'page');
    btn.appendChild(icon);
    btn.appendChild(label);
    btn.addEventListener('click', () => {
      window.dispatchEvent(new CustomEvent(tab.eventName));
    });
    tabs.appendChild(btn);
  }

  host.appendChild(tabs);
}

/**
 * Cycle the shared character-menu tabs from keyboard handlers.
 * @param {string} activeKey
 * @param {boolean} reverse
 */
export function dispatchCharacterMenuTabCycle(activeKey, reverse = false) {
  const current = CHARACTER_MENU_TABS.findIndex((tab) => tab.key === activeKey);
  const start = current >= 0 ? current : 0;
  const dir = reverse ? -1 : 1;
  const next = (start + dir + CHARACTER_MENU_TABS.length) % CHARACTER_MENU_TABS.length;
  const tab = CHARACTER_MENU_TABS[next];
  if (tab?.eventName) window.dispatchEvent(new CustomEvent(tab.eventName));
}

/**
 * Mark an element as intentionally scrollable under global input lockdown.
 * @param {HTMLElement} el
 */
export function markScrollable(el) {
  if (!(el instanceof HTMLElement)) return;
  el.dataset.allowScroll = 'true';
  el.style.touchAction = 'pan-y';
  el.style.overscrollBehavior = 'contain';
}

/**
 * @param {any} item
 * @returns {string}
 */
export function quickPinKeyForItem(item) {
  const identity = String(item?.identity || item?.details?.identity || '');
  if (identity) return identity;
  const id = Number(item?.id || 0) | 0;
  return id > 0 ? `id:${id}` : '';
}

export function ensureRoot() {
  let root = document.getElementById('ui-root');
  if (!root) {
    root = document.createElement('div');
    root.id = 'ui-root';
    root.style.position = 'fixed';
    root.style.left = '0';
    root.style.top = '0';
    root.style.right = '0';
    root.style.bottom = '0';
    root.style.pointerEvents = 'none';
    root.style.zIndex = String(UI_ROOT_Z_INDEX);
    document.body.appendChild(root);
  }
  return root;
}

// --- Gesture debug overlay -------------------------------------------------
export function ensureGestureDebugLayer(root) {
  const canvas = document.createElement('canvas');
  canvas.id = 'gesture-debug-layer';
  Object.assign(canvas.style, {
    position: 'fixed',
    left: '0', top: '0', right: '0', bottom: '0',
    width: '100vw', height: '100vh',
    pointerEvents: 'none',
    zIndex: '1220',
    display: 'none',
    pointerEvents: 'auto',
    touchAction: 'manipulation',
  });
  Object.assign(trapDodgeBtn.style, {
    position: 'absolute',
    inset: '0',
    border: '1px solid rgba(255,255,255,0.48)',
    borderRadius: '8px',
    background: 'rgba(22,24,28,0.92)',
    color: '#fff7d7',
    font: '700 16px/1 system-ui, sans-serif',
    letterSpacing: '0',
    textTransform: 'uppercase',
    boxShadow: '0 12px 30px rgba(0,0,0,0.42), 0 0 24px rgba(255,92,42,0.28)',
    overflow: 'hidden',
  });
  Object.assign(trapDodgeLabel.style, {
    position: 'relative',
    zIndex: '1',
    paddingTop: '10px',
  });
  Object.assign(trapDodgeStat.style, {
    position: 'relative',
    zIndex: '1',
    marginTop: '3px',
    color: '#ffd166',
    font: '600 10px/1 system-ui, sans-serif',
  });
  Object.assign(trapDodgeFill.style, {
    position: 'absolute',
    left: '0',
    bottom: '0',
    width: '100%',
    height: '5px',
    background: 'linear-gradient(90deg, #f05b35, #ffd166)',
    transformOrigin: 'left center',
    transform: 'scaleX(1)',
    pointerEvents: 'none',
  });
  trapDodgeLabel.textContent = 'Dodge';
  trapDodgeStat.textContent = 'EVA 0';
  trapDodgeBtn.appendChild(trapDodgeLabel);
  trapDodgeBtn.appendChild(trapDodgeStat);
  trapDodgeBtn.appendChild(trapDodgeFill);
  trapDodge.appendChild(trapDodgeBtn);
  root.appendChild(trapDodge);
  let trapDodgePrompt = null;
  let trapDodgeRaf = 0;

  function finishTrapDodge(dodged) {
    if (!trapDodgePrompt) return;
    const prompt = trapDodgePrompt;
    trapDodgePrompt = null;
    if (trapDodgeRaf) {
      cancelAnimationFrame(trapDodgeRaf);
      trapDodgeRaf = 0;
    }
    trapDodge.style.display = 'none';
    setInputLock('trapDodge', false);
    window.dispatchEvent(new CustomEvent('ui:trapDodgeResolved', {
      detail: {
        promptId: prompt.promptId,
        victimId: prompt.victimId,
        trapId: prompt.trapId,
        dodged,
      },
    }));
  }

  function showTrapDodgePrompt(detail) {
    const durationMs = Math.max(250, Number(detail?.durationMs || 0) | 0);
    const angle = Number(detail?.angleDeg || 0) * Math.PI / 180;
    const shortSide = Math.min(window.innerWidth || 0, window.innerHeight || 0);
    const radius = Math.max(92, Math.min(210, shortSide * 0.28));
    const cx = (window.innerWidth || 0) * 0.5;
    const cy = (window.innerHeight || 0) * 0.5;
    const margin = 68;
    const x = Math.max(margin, Math.min((window.innerWidth || 0) - margin, cx + Math.cos(angle) * radius));
    const y = Math.max(margin, Math.min((window.innerHeight || 0) - margin, cy + Math.sin(angle) * radius));
    trapDodgePrompt = {
      promptId: String(detail?.promptId || ''),
      victimId: Number(detail?.victimId || 0) | 0,
      trapId: Number(detail?.trapId || 0) | 0,
      startedAt: performance.now(),
      durationMs,
    };
    trapDodge.style.left = `${x}px`;
    trapDodge.style.top = `${y}px`;
    trapDodgeFill.style.transform = 'scaleX(1)';
    trapDodgeStat.textContent = `EVA ${Number(detail?.evade || 0) | 0}`;
    trapDodge.style.display = 'block';
    setInputLock('trapDodge', true);
    trapDodgeBtn.focus({ preventScroll: true });

    const tick = () => {
      if (!trapDodgePrompt) return;
      const elapsed = performance.now() - trapDodgePrompt.startedAt;
      const remaining = Math.max(0, 1 - elapsed / trapDodgePrompt.durationMs);
      trapDodgeFill.style.transform = `scaleX(${remaining})`;
      if (remaining <= 0) {
        finishTrapDodge(false);
        return;
      }
      trapDodgeRaf = requestAnimationFrame(tick);
    };
    if (trapDodgeRaf) cancelAnimationFrame(trapDodgeRaf);
    trapDodgeRaf = requestAnimationFrame(tick);
  }

  trapDodgeBtn.addEventListener('pointerdown', (ev) => {
    ev.preventDefault();
    ev.stopPropagation();
    finishTrapDodge(true);
